const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Define Cambodia geometry (using FAO GAUL dataset)
    var cambodia = ee.FeatureCollection('FAO/GAUL/2015/level0')
        .filter(ee.Filter.eq('ADM0_NAME', 'Cambodia'));

    // Check if geometry exists
    var geomSize = cambodia.size().getInfo();
    if (geomSize === 0) {
        // Fallback: rough bounding box for Cambodia
        cambodia = ee.Geometry.Polygon([[
            [102.5, 14.5],
            [102.5, 10.5],
            [107.5, 10.5],
            [107.5, 14.5]
        ]]);
        console.log('Used bounding box for Cambodia.');
    } else {
        cambodia = cambodia.geometry();
        console.log('Loaded Cambodia boundary from FAO GAUL.');
    }

    // 2. Load Hansen Global Forest Change dataset (latest version)
    var hansen = ee.Image('UMD/hansen/global_forest_change_2022_v1_10');

    // Check if image exists by trying to get a property
    try {
        var bandNames = hansen.bandNames().getInfo();
        console.log('Hansen bands available:', bandNames);
    } catch (e) {
        console.log('Hansen dataset not accessible:', e.message);
        console.log('<answer>D</answer>');
        return;
    }

    // 3. Extract lossyear band (1-14 corresponds to 2001-2014)
    var lossyear = hansen.select('lossyear');

    // Create mask for forest loss between 2001-2014 (values 1-14)
    var lossMask = lossyear.gte(1).and(lossyear.lte(14));

    // 4. Count pixels with forest loss in the period
    var lossCount = lossMask.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: cambodia,
        scale: 1000,
        maxPixels: 1e10
    }).get('lossyear');

    var totalLossPixels;
    try {
        totalLossPixels = lossCount.getInfo();
    } catch (e) {
        console.log('Failed to compute loss count:', e.message);
        console.log('<answer>D</answer>');
        return;
    }

    // 5. Also count total forest area in 2000 for context (optional)
    var treecover2000 = hansen.select('treecover2000');
    var forestMask2000 = treecover2000.gte(30);  // 30% tree cover threshold

    var forestArea2000 = forestMask2000.reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: cambodia,
        scale: 1000,
        maxPixels: 1e10
    }).get('treecover2000');

    var totalForestPixels;
    try {
        totalForestPixels = forestArea2000.getInfo();
    } catch (e) {
        totalForestPixels = null;
    }

    // 6. Print concise evidence
    console.log('Forest loss pixels (2001-2014):', totalLossPixels);
    if (totalForestPixels !== null) {
        console.log('Forest pixels (2000, ≥30% cover):', totalForestPixels);
    }

    // 7. Validate and determine answer
    if (totalLossPixels === null || typeof totalLossPixels === 'undefined') {
        console.log('Calculation failed: loss count is null/undefined.');
        console.log('<answer>C3</answer>');
    } else if (isNaN(totalLossPixels)) {
        console.log('Calculation failed: loss count is NaN.');
        console.log('<answer>C3</answer>');
    } else if (totalLossPixels > 0) {
        console.log('Forest loss detected between 2001-2014.');
        console.log('<answer>A</answer>');
    } else if (totalLossPixels === 0) {
        console.log('No forest loss detected between 2001-2014.');
        console.log('<answer>B</answer>');
    } else {
        // Negative or other unexpected value
        console.log('Unexpected loss count value:', totalLossPixels);
        console.log('<answer>C3</answer>');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
